    /// <summary>
    /// The option to relax the validation needed to update a dashboard with definition objects. This skips the validation step for specific er- rors. Mode -&gt; (string) [required] The mode of validation for the asset to be created or updated. When you set this value to STRICT , strict validation for every error is enforced. When you set this value to LENIENT , valida- tion is skipped for specific UI errors. Possible values: o STRICT o LENIENT Shorthand Syntax: Mode=string JSON Syntax: { "Mode": "STRICT"|"LENIENT" }
    /// </summary>
    [CliOption("--validation-strategy")]
    public string? ValidationStrategy { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

